  q(SPEC,'What is the best urine specimen for a pregnancy test?','First morning specimen',['Random afternoon specimen','24-hour collection','Specimen after exercise'],'A','First morning urine is most concentrated, so hCG is easiest to detect.',BLESI),
  q(SPEC,'How should a stool specimen for ova and parasites be handled?','Placed in preservative and sent promptly',['Frozen for one week','Mixed with urine','Left at room temperature for days'],'C','Parasites can break down quickly, so timing and preservatives are important.',BLESI),
  q(SPEC,'Which tube is used for a CBC?','Lavender top (EDTA)',['Red top','Light blue top','Gray top'],'B','EDTA prevents clotting by binding calcium and preserves blood cells.',BLESI),
  q(SPEC,'What should be written on a specimen label?','Patient name, ID, date, time and initials',['Only the patient’s first name','Only the test name','The provider’s home address'],'D','Labels must match the requisition. Unlabeled specimens are rejected.',BLESI),
  q(SPEC,'What is a 24-hour urine collection used for?','Measuring daily output',['Checking for pregnancy','Detecting illegal drugs only','A quick dipstick test'],'A','Discard the first void, then collect all urine for 24 hours, including the final void.',BLESI),
  q(DX,'What does a normal ECG P wave represent?','Atrial depolarization',['Ventricular depolarization','Ventricular repolarization','Atrial repolarization'],'C','The QRS complex is ventricular depolarization and the T wave is ventricular repolarization.',BLESI),
  q(DX,'Which test measures how well blood clots in a patient taking warfarin?','PT/INR',['Hemoglobin A1c','Lipid panel','Urinalysis'],'B','The INR standardizes PT results so warfarin doses can be adjusted.',BLESI),
  q(DX,'Which chart is used to test distance visual acuity?','Snellen chart',['Ishihara plates','Jaeger card','Amsler grid'],'D','Ishihara plates test color vision and the Jaeger card tests near vision.',BLESI),
  q(DX,'What is the normal fasting blood glucose range for adults?','70–99 mg/dL',['40–60 mg/dL','100–125 mg/dL','126–200 mg/dL'],'A','100–125 mg/dL suggests prediabetes and 126 mg/dL or higher on two tests suggests diabetes.',BLESI),
  q(DX,'Which diagnostic imaging test uses magnets and radio waves?','MRI',['CT','X-ray','PET'],'C','Patients must be screened for metal implants and devices before an MRI.',BLESI),
  q(CLIN,'Which site is used for an intradermal injection, such as a TB skin test?','Inner forearm',['Deltoid muscle','Vastus lateralis','Abdomen'],'B','Inject at a 10–15 degree angle to raise a small wheal. Read the test in 48–72 hours.',BLESI),
  q(CLIN,'Which needle is most appropriate for an adult intramuscular injection in the deltoid?','22–25 gauge, 1 inch',['27 gauge, ⅜ inch','18 gauge, 3 inches','30 gauge, ½ inch'],'D','Needle length depends on the patient’s size and the amount of tissue over the muscle.',BLESI),
  q(CLIN,'Which is one of the “rights” of medication administration?','Right route',['Right price','Right pharmacy','Right brand'],'A','Rights include patient, drug, dose, route, time and documentation.',BLESI),
  q(CLIN,'What should an MA do if a patient faints during a procedure?','Lower the patient safely and get help',['Leave to call the family','Give water right away','Have the patient stand'],'C','Protect the patient from injury, check breathing and alert the provider.',BLESI),
  q(CLIN,'Which instrument is used to grasp tissue?','Forceps',['Scalpel','Probe','Speculum'],'B','A scalpel cuts, a probe explores and a speculum opens a body cavity for viewing.',BLESI),
  q(EXAM,'Which position is used for a patient with breathing problems?','Fowler’s',['Prone','Trendelenburg','Lithotomy'],'D','Fowler’s position raises the head of the table 45 to 90 degrees to ease breathing.',BLESI),
  q(EXAM,'Which examination technique uses the hands to feel body parts?','Palpation',['Auscultation','Inspection','Percussion'],'A','Auscultation is listening, inspection is looking and percussion is tapping.',BLESI),
  q(EXAM,'Where is the apical pulse counted?','Over the apex of the heart',['On the thumb side of the wrist','Behind the knee','On top of the foot'],'C','Listen for a full minute with a stethoscope. It is used for infants and patients taking heart medicine.',BLESI),
  q(EXAM,'Which blood pressure reading is classified as stage 1 hypertension?','134/84 mm Hg',['118/76 mm Hg','124/78 mm Hg','150/96 mm Hg'],'B','Stage 1 is 130–139 systolic or 80–89 diastolic; stage 2 is 140/90 or higher.',BLESI),
  q(EXAM,'Which instrument is used to examine the ear canal and eardrum?','Otoscope',['Ophthalmoscope','Sphygmomanometer','Tuning fork'],'D','An ophthalmoscope examines the eye, and a tuning fork tests hearing.',BLESI)
